import math
def tanh(x):
    return (math.exp(x) - math.exp(-x)) / (math.exp(x) + math.exp(-x))
w = [-18.0, -4.0]
for theta, omega in [(0.12, 0.0), (0.05, 0.3), (-0.08, -0.2)]:
    h = tanh(w[0] * theta + w[1] * omega)
    print('theta', theta, 'omega', omega, 'hidden', round(h, 4), 'control', round(6.0 * h, 4))

